export default async ({ state }, context) => {
  if (state.ids.length !== state.total)
    throw new Error("WordPress did not return the complete post collection");
  const name = "Wordpress-Posts.csv";
  const bytes = new TextEncoder().encode(state.text);
  if (bytes.length !== state.byteCount) throw new Error("The CSV byte count changed unexpectedly");
  const file = await context.artifact.put(bytes, { name, mediaType: "text/csv" });
  return { file, rows: state.total };
};

