function encodeArtifact(bytes) {
  let contentBase64 = "";
  for (let offset = 0; offset < bytes.length; offset += 12288) {
    contentBase64 += btoa(String.fromCharCode(...bytes.subarray(offset, offset + 12288)));
  }
  return contentBase64;
}

export default async ({ file, folder }, context) => {
  const bytes = await context.artifact.open(file);
  return { name: file.name, parents: [folder], contentBase64: encodeArtifact(bytes) };
};

