function driveReceipt(file, { folder, name, byteCount }) {
  if (
    !file?.id ||
    file.name !== name ||
    file.mimeType !== "text/csv" ||
    String(file.size) !== String(byteCount) ||
    !Array.isArray(file.parents) ||
    !file.parents.length ||
    (folder !== "root" && !file.parents.includes(folder))
  ) {
    throw new Error(
      "Google Drive did not confirm the complete CSV in the selected folder. Review Drive before retrying.",
    );
  }
  return { fileId: file.id, sizeBytes: byteCount };
}

export default ({ id, name, mimeType, parents, sizeBytes, file, folder, rows }) => ({
  status: {
    rows,
    ...driveReceipt(
      { id, name, mimeType, parents, size: sizeBytes },
      { folder, name: file.name, byteCount: file.size },
    ),
  },
});
